<?php require_once __DIR__.'/includes/auth.php';customer_required();$u=customer_user();$s=$pdo->prepare('SELECT * FROM orders WHERE user_id=? ORDER BY id DESC');$s->execute([$_SESSION['user_id']]);$orders=$s->fetchAll();$page_title='My Account — MediNova';require __DIR__.'/includes/store_header.php';?><section class="page-hero" style="min-height:38vh"><p class="kicker">CUSTOMER AREA</p><h1>My <span>account.</span></h1><p>Welcome, <?=e($u['name'])?>. Your private customer dashboard is separate from the MediNova admin system.</p></section><section class="content-section"><div class="account-grid"><nav class="account-nav"><a href="account.php">Orders</a><a href="shop.php">Continue shopping</a><a href="logout.php">Logout</a></nav><div class="glass-card"><p class="kicker">ORDER HISTORY</p><?php if(!$orders):?><div class="empty-state">You have not placed an order yet.</div><?php else:?><table class="orders-table"><tr><th>Order</th><th>Total</th><th>Payment</th><th>Status</th><th>Date</th></tr><?php foreach($orders as $o):?><tr><td>#MN<?=$o['id']?></td><td>Rs. <?=number_format($o['total'])?></td><td><?=e($o['payment_method'])?> / <?=e($o['payment_status'])?></td><td><span class="status"><?=e($o['status'])?></span></td><td><?=date('d M Y',strtotime($o['created_at']))?></td></tr><?php endforeach;?></table><?php endif;?></div></div></section><?php require __DIR__.'/includes/store_footer.php'; ?>
